    assert.equal(quotedIdentifier(''), '""');

    // Identifier with special characters
    assert.equal(quotedIdentifier('table-name'), '"table-name"');
    assert.equal(quotedIdentifier('table.name'), '"table.name"');
    assert.equal(quotedIdentifier('table name'), '"table name"');
  });
});

